#!/usr/bin/env python3
"""Build the pinned embedded zlib-ng version as a native Apple candidate."""
import argparse,hashlib,json,pathlib,subprocess
R=pathlib.Path(__file__).resolve().parents[1];ap=argparse.ArgumentParser();ap.add_argument('--platform',choices=['macos','device','simulator'],default='macos');a=ap.parse_args();sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();pin=next(v for v in json.loads((R/'dependencies.lock.json').read_text())['sources'] if v['name']=='zlib-ng-embedded-reference');src=R/pin['path'];assert subprocess.check_output(['git','-C',str(src),'rev-parse','HEAD'],text=True).strip()==pin['revision']
for name,h in pin['files'].items():assert sha(src/name)==h,name
out=R/'generated/zlib-ng'/a.platform;out.mkdir(parents=True,exist_ok=True);build=out/'build';sdkname='macosx' if a.platform=='macos' else 'iphoneos' if a.platform=='device' else 'iphonesimulator';sdk=subprocess.check_output(['xcrun','--sdk',sdkname,'--show-sdk-path'],text=True).strip();cmd=['cmake','-S',str(src),'-B',str(build),'-DCMAKE_BUILD_TYPE=Release','-DBUILD_SHARED_LIBS=OFF','-DZLIB_COMPAT=OFF','-DZLIB_ENABLE_TESTS=OFF','-DZLIBNG_ENABLE_TESTS=OFF','-DWITH_GTEST=OFF','-DWITH_BENCHMARKS=OFF','-DWITH_NATIVE_INSTRUCTIONS=OFF','-DCMAKE_OSX_ARCHITECTURES=arm64','-DCMAKE_OSX_SYSROOT='+sdk,'-DCMAKE_OSX_DEPLOYMENT_TARGET='+('12.0' if a.platform=='macos' else '16.0')]
if a.platform!='macos':cmd+=['-DCMAKE_SYSTEM_NAME=iOS','-DCMAKE_TRY_COMPILE_TARGET_TYPE=STATIC_LIBRARY']
with (out/'configure.log').open('w') as log:subprocess.run(cmd,stdout=log,stderr=subprocess.STDOUT,check=True)
with (out/'build.log').open('w') as log:subprocess.run(['cmake','--build',str(build),'--parallel','4'],stdout=log,stderr=subprocess.STDOUT,check=True)
lib=build/'libz-ng.a';assert lib.exists()
adapter=R/'port/core/guest_zlib.c';adapter_object=out/'guest_zlib.o';target={'macos':'arm64-apple-macos12','device':'arm64-apple-ios16','simulator':'arm64-apple-ios16-simulator'}[a.platform]
adapter_command=['clang','-target',target,'-isysroot',sdk,'-O2','-DPTROFS_64BIT','-Wall','-Wextra','-Werror','-I',str(build),'-I',str(src),'-c',str(adapter),'-o',str(adapter_object)]
subprocess.run(adapter_command,check=True)
chunk_adapter=R/'port/core/guest_zlib_chunk.c';chunk_object=out/'guest_zlib_chunk.o';chunk_command=adapter_command[:-4]+['-c',str(chunk_adapter),'-o',str(chunk_object)]
subprocess.run(chunk_command,check=True)
tracked=subprocess.check_output(['git','-C',str(src),'ls-files'],text=True).splitlines();report={'pass':True,'platform':a.platform,'revision':pin['revision'],'source_sha256':{n:sha(src/n) for n in tracked if (src/n).is_file()},'library':str(lib.relative_to(R)),'library_sha256':sha(lib),'adapter':{'object':str(adapter_object.relative_to(R)),'object_sha256':sha(adapter_object),'source_sha256':sha(adapter),'header_sha256':sha(R/'port/core/guest_zlib.h'),'command':adapter_command},'chunk_adapter':{'object':str(chunk_object.relative_to(R)),'object_sha256':sha(chunk_object),'source_sha256':sha(chunk_adapter),'command':chunk_command},'configure_command':cmd,'cache_sha256':sha(build/'CMakeCache.txt'),'sdk':sdk,'scope':'Native ARM64 static compression library candidate from embedded upstream version. Buffer-only guest adapter compiled. No guest stream structure/callback ABI adapter or image routing, full client link, game execution or online claim.'};(out/'result.json').write_text(json.dumps(report,indent=2)+'\n');print('PASS: native zlib-ng 2.2.3 static candidate '+a.platform)
